contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller) public payable {
        require(caller != address(this));

        bool reverted;
        vm.prank(caller);
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(caller == address(this) || reverted);
    }
}

