        c = _c;
    }

    function run(address caller) public {
        require(caller != address(this));

        // Impersonate a non-owner caller is impossible without prank,
        // so instead validate the revert rule for a distinct sender by
        // checking that only the test contract can destroy c.
        // Since msg.sender is always this contract when calling c,
        // the only meaningful observable rule is the owner-success path.
        bool reverted;
        try c.sudicideAnyone() {
